import{_ as e,o as a,c as n,a2 as d}from"./chunks/framework.CDU0sSpB.js";const u=JSON.parse('{"title":"原生 Agent Runtime","description":"Hearth 如何用 Pi 式单 Agent 工具循环完成通用任务，并把权限、预算、检查点和恢复放在任务边界内。","frontmatter":{"title":"原生 Agent Runtime","description":"Hearth 如何用 Pi 式单 Agent 工具循环完成通用任务，并把权限、预算、检查点和恢复放在任务边界内。","outline":[2,3]},"headers":[],"relativePath":"design/native-agent-runtime.md","filePath":"design/native-agent-runtime.md","lastUpdated":1793970107000}'),i={name:"design/native-agent-runtime.md"};function s(l,t,o,r,p,c){return a(),n("div",null,[...t[0]||(t[0]=[d(`<h1 id="原生-agent-runtime" tabindex="-1">原生 Agent Runtime <a class="header-anchor" href="#原生-agent-runtime" aria-label="Permalink to &quot;原生 Agent Runtime&quot;">​</a></h1><p class="lead">Hearth 的原生执行器不是一段“把任务发给模型”的提示词，而是一个可暂停、可恢复、受权限和预算约束的单 Agent 工具循环。它参考 Pi 的简洁内核形态，由 Hearth 自己实现，不依赖 Pi 的 npm 包。</p><h2 id="为什么自研-runtime" tabindex="-1">为什么自研 Runtime <a class="header-anchor" href="#为什么自研-runtime" aria-label="Permalink to &quot;为什么自研 Runtime&quot;">​</a></h2><p>聊天模型可以回答问题，但不能直接证明工作真的完成。要形成闭环，系统必须自己保存消息、执行工具、累计用量、限制权限、写入检查点，并在缺少产物时继续补齐。把这些职责交给外部 CLI 会让任务状态、权限和恢复语义分裂在两个进程里。</p><p>Hearth 因此保留两层执行能力：</p><table tabindex="0"><thead><tr><th>执行器</th><th>定位</th><th>典型任务</th></tr></thead><tbody><tr><td><code>native</code></td><td>通用单 Agent，直接调用当前聊天模型和内置工具</td><td>整理资料、生成文档、分析网页、简单文件处理</td></tr><tr><td><code>codex</code></td><td>面向代码仓库和多文件工程的专长执行器</td><td>修复项目错误、修改代码、运行测试、提交改动</td></tr></tbody></table><p>原生执行器是默认的通用路径。只有明确属于仓库或工程工作时，路由器才选择 Codex；两者不会在失败后静默互换。</p><h2 id="内核形态" tabindex="-1">内核形态 <a class="header-anchor" href="#内核形态" aria-label="Permalink to &quot;内核形态&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>任务 + 用户补充</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span> 系统提示 + 消息历史</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span> 模型流式回合 ──→ 文本回答 / 工具调用</span></span>
<span class="line"><span>      ↓                    ↓</span></span>
<span class="line"><span> Token 与预算累计      执行受权限约束的工具</span></span>
<span class="line"><span>      ↓                    ↓</span></span>
<span class="line"><span>  写入检查点 ←──── 工具结果回填</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span> 完成 / 暂停等待输入 / 预算耗尽 / 取消</span></span></code></pre></div><p>每轮只做一件事：模型返回内容与工具调用，Runtime 执行工具并把结果作为下一条消息回填。任务完成的唯一可信信号是模型调用 <code>finish_task</code>，以及声明的产物确实存在且非空。</p><h2 id="消息与协议" tabindex="-1">消息与协议 <a class="header-anchor" href="#消息与协议" aria-label="Permalink to &quot;消息与协议&quot;">​</a></h2><p><code>@hearth/model-client</code> 负责四种协议：OpenAI Chat Completions、OpenAI Responses、Anthropic Messages 和 Gemini。<code>model-agent.ts</code> 把它们统一成同一种流式 Agent 回合：文本增量、工具调用、工具参数拼接、结束原因和用量。</p><p>这样更换模型提供商不会改变 Runtime 的工具循环，也不需要为每家模型复制一套调度逻辑。原生执行器要求模型支持工具调用；不支持时直接给出明确错误，不伪装成成功。</p><h2 id="内置工具" tabindex="-1">内置工具 <a class="header-anchor" href="#内置工具" aria-label="Permalink to &quot;内置工具&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>用途</th><th>默认边界</th></tr></thead><tbody><tr><td><code>read_file</code>、<code>list_files</code>、<code>search_text</code></td><td>读取任务工作区与输入材料</td><td>只能访问任务工作区和授权目录</td></tr><tr><td><code>write_file</code>、<code>edit_file</code>、<code>apply_patch</code></td><td>生成和修改用户产物</td><td>只能写入输出目录；工作区任务可写隔离工作区</td></tr><tr><td><code>shell</code></td><td>运行必要检查命令</td><td>只在工作区任务中授权；危险命令拦截</td></tr><tr><td><code>fetch_url</code></td><td>读取任务声明的网页</td><td>网络默认拒绝，只允许任务授权的域名</td></tr><tr><td><code>ask_user</code></td><td>缺少关键信息时暂停</td><td>进入 <code>waiting_input</code>，不继续猜测</td></tr><tr><td><code>finish_task</code></td><td>声明完成并给出中文总结</td><td>仍需通过产物检查</td></tr></tbody></table><p>符号链接逃逸、路径越界、私有地址和未授权域名都在工具层拒绝。权限按任务固定，不在执行过程中由模型自行扩大。</p><h2 id="预算、检查点与恢复" tabindex="-1">预算、检查点与恢复 <a class="header-anchor" href="#预算、检查点与恢复" aria-label="Permalink to &quot;预算、检查点与恢复&quot;">​</a></h2><p>每次原生运行都有四类预算：最大轮次、最大工具调用次数、最大 Token 和最大时长。超过预算会停止并返回可解释的结果，不继续消耗。</p><p>Runtime 在每个模型回合、每个工具步骤、等待输入和最终完成时写入检查点。检查点包含消息、用量、轮次和工具调用计数。恢复时：</p><ol><li>找到最近一次可恢复的检查点，复制当时的工作区。</li><li>恢复消息与预算计数，必要时把用户补充作为新的 <code>user</code> 消息追加。</li><li>从暂停位置继续，而不是从头重跑。</li><li>最终产物缺失时，带着上一轮 Agent 上下文补交，最多两轮；仍不满足则明确失败。</li></ol><p>检查点存放在隔离工作区的 <code>.hearth/checkpoints/</code> 下，任务详情只展示数量和折叠的技术信息，不把中间 JSON 当作用户产物。</p><h2 id="完成契约" tabindex="-1">完成契约 <a class="header-anchor" href="#完成契约" aria-label="Permalink to &quot;完成契约&quot;">​</a></h2><ul><li>通用与交付任务必须生成声明的产物，默认是 <code>result.md</code>。</li><li>工作区任务必须给出最终总结，并保留代码改动和测试证据。</li><li>中间 JSON、命令日志、检查点和运行时文件不进入用户产物列表。</li><li>声明的产物为空、执行器没有返回总结或预算耗尽，都不能标记为完成。</li><li>用户需要的最终结果出现在任务详情顶部；执行命令、检查点和内部事件收进折叠区域。</li></ul><h2 id="任务提案" tabindex="-1">任务提案 <a class="header-anchor" href="#任务提案" aria-label="Permalink to &quot;任务提案&quot;">​</a></h2><p>需要联网或读写工程工作区的任务，先在聊天中生成任务提案，而不是直接执行。提案说明执行器、任务类型、期望产物、网络域名和原因。用户确认后才创建任务并进入调度队列；拒绝则不产生任务。</p><p>普通通用任务可以直接派出。这样既保持“说一句话就开始”的简单交互，又让高权限动作有明确的用户授权点。</p><h2 id="当前边界" tabindex="-1">当前边界 <a class="header-anchor" href="#当前边界" aria-label="Permalink to &quot;当前边界&quot;">​</a></h2><ul><li>首版是单 Agent，不做子代理并行和自动生成团队。</li><li>执行使用当前聊天模型，不内置第二套“执行模型”。</li><li>网络默认拒绝，工作区按任务隔离。</li><li>不把中间步骤、内部 JSON 或终端输出当作交付结果。</li><li>不追求复刻 Pi 的全部扩展机制；只采用清晰的消息循环、工具边界和可恢复状态。</li></ul>`,28)])])}const m=e(i,[["render",s]]);export{u as __pageData,m as default};
